rules:
@-moz-document url-prefix("mailbox:"), url-prefix("imap:"), url-prefix("imaps:"), url-prefix("file:"), url("about:blank") { .moz-text-plain, .moz-text-flowed, .aven-letter { font-family: "Noto Sans", sans-serif !important; font-size: 16px !important; line-height: 1.65 !important; font-weight: 400; } .moz-text-plain:lang(zh), .moz-text-flowed:lang(zh), .aven-letter:lang(zh) { font-size: 17px !important; line-height: 1.75 !important; } .aven-letter { max-inline-size: 42rem; margin-inline: auto; padding: 16px 24px; } .aven-letter p { margin-block: 0px 1em; } .aven-letter:lang(zh-CN), .aven-letter:lang(zh-SG) { font-family: "Noto Sans", "Noto Sans CJK SC", sans-serif !important; } .aven-letter:lang(zh-TW) { font-family: "Noto Sans", "Noto Sans CJK TC", sans-serif !important; } .aven-letter:lang(zh-HK) { font-family: "Noto Sans", "Noto Sans CJK HK", sans-serif !important; } .moz-text-plain pre, .moz-text-flowed pre, .aven-letter pre, .aven-letter code { font-family: "Noto Sans Mono", monospace !important; font-size: 14px !important; } @media (prefers-color-scheme: light) and (prefers-contrast: no-preference) {
  body:has(> .aven-letter), body:has(> .moz-text-plain), body:has(> .moz-text-flowed) { background: rgb(253, 252, 249) !important; color: rgb(38, 52, 47) !important; }
} }
